contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address to, uint256 amount, uint256 initialAllowance) public payable {
        require(from != address(0));
        require(to != address(0));
        require(to != from);
        require(initialAllowance >= amount);
        require(msg.sender != from);
        uint oldAllow = c.allowance(from, msg.sender);
        require(oldAllow == initialAllowance);
        uint oldFromBal = c.balanceOf(from);
        require(oldFromBal >= amount);
        c.transferFrom(from, to, amount);
        uint newAllow = c.allowance(from, msg.sender);
        assert(newAllow == oldAllow - amount);
    }
}

contract InvMutTest {
