    function run(uint256 amount) public payable {
        require(amount > 0);
        uint256 beforeAllow = c.allowance(address(this), address(this));
        c.approve(address(this), amount);
        bool success = c.transferFrom(address(this), address(0x1), amount);
        uint256 afterAllow = c.allowance(address(this), address(this));
        assert(!success || afterAllow == beforeAllow);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address to, uint amount) public payable {
        require(from != address(0) && to != address(0));
        require(amount > 0);
        require(c.allowance(from, address(this)) >= amount);
        require(c.balanceOf(from) >= amount);
        uint oldAllowance = c.allowance(from, address(this));
        c.transferFrom(from, to, amount);
        uint newAllowance = c.allowance(from, address(this));
        assert(!(oldAllowance == amount) || newAllowance == 0);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address _from, address _to, uint256 _amount, uint256 _extra) public payable {
        require(_extra > 0);
        uint256 oldAllow = c.allowance(_from, address(this));
        require(oldAllow >= _amount + _extra);
        c.transferFrom(_from, _to, _amount);
        uint256 newAllow = c.allowance(_from, address(this));
        assert(newAllow <= oldAllow - _amount - 1);
    }
}
